const report = $json;
const expectedKeys = [
  'report_version',
  'report_type',
  'report_key',
  'business_date',
  'business_timezone',
  'window_start_utc',
  'window_end_utc',
  'generated_at',
  'leads_received',
  'furnace_requests',
  'air_conditioning_requests',
  'other_or_unknown_requests',
  'needs_review',
  'appointments_booked',
  'follow_ups_sent',
  'open_recovery_incidents_at_generated_at',
];
const countFields = [
  'leads_received',
  'furnace_requests',
  'air_conditioning_requests',
  'other_or_unknown_requests',
  'needs_review',
  'appointments_booked',
  'follow_ups_sent',
  'open_recovery_incidents_at_generated_at',
];
const isPlainObject = report && typeof report === 'object' && !Array.isArray(report) && Object.prototype.toString.call(report) === '[object Object]';
if (!isPlainObject) throw new Error('Management report must be a plain object.');
const actualKeys = Object.keys(report).sort();
const sortedExpectedKeys = [...expectedKeys].sort();
if (actualKeys.length !== sortedExpectedKeys.length || actualKeys.some((key, index) => key !== sortedExpectedKeys[index])) throw new Error('Management report field set is invalid.');
if (report.report_version !== 1 || report.report_type !== 'hvac_management_snapshot') throw new Error('Management report version or type is invalid.');
if (typeof report.business_date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(report.business_date)) throw new Error('Management report business date is invalid.');
const [year, month, day] = report.business_date.split('-').map(Number);
if (new Date(Date.UTC(year, month - 1, day)).toISOString().slice(0, 10) !== report.business_date) throw new Error('Management report business date does not exist.');
if (report.report_key !== `hvac-daily:${report.business_date}`) throw new Error('Management report identity is invalid.');
if (report.business_timezone !== 'America/Vancouver') throw new Error('Management report timezone is invalid.');
const timestampFields = ['window_start_utc', 'window_end_utc', 'generated_at'];
for (const field of timestampFields) {
  const value = report[field];
  if (typeof value !== 'string' || !/(?:Z|[+-]\d{2}:\d{2})$/.test(value) || Number.isNaN(Date.parse(value))) throw new Error(`Management report ${field} is invalid.`);
}
const vancouverParts = (value) => Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Vancouver', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(value)).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
const startLocal = vancouverParts(report.window_start_utc);
const endLocal = vancouverParts(report.window_end_utc);
const startDate = `${startLocal.year}-${startLocal.month}-${startLocal.day}`;
const endDate = `${endLocal.year}-${endLocal.month}-${endLocal.day}`;
const nextBusinessDate = new Date(Date.UTC(year, month - 1, day + 1)).toISOString().slice(0, 10);
if (startDate !== report.business_date || endDate !== nextBusinessDate || startLocal.hour !== '00' || startLocal.minute !== '00' || startLocal.second !== '00' || endLocal.hour !== '00' || endLocal.minute !== '00' || endLocal.second !== '00') throw new Error('Management report window does not match Vancouver business-day boundaries.');
const windowMilliseconds = Date.parse(report.window_end_utc) - Date.parse(report.window_start_utc);
if (windowMilliseconds < 23 * 60 * 60 * 1000 || windowMilliseconds > 25 * 60 * 60 * 1000) throw new Error('Management report window is invalid.');
for (const field of countFields) {
  if (!Number.isSafeInteger(report[field]) || report[field] < 0) throw new Error(`Management report ${field} must be a non-negative safe integer.`);
}
if (report.furnace_requests + report.air_conditioning_requests + report.other_or_unknown_requests !== report.leads_received) throw new Error('Management report lead categories do not reconcile.');
return [{ json: report }];

const result = $json;
const report = $('Validate Management Report Contract').first().json;
const error = result?.error || null;
if (error) {
  const safeErrorText = typeof error === 'object' ? [error.code, error.name, error.message].filter((value) => typeof value === 'string').join(' ') : String(error);
  if (/timeout|timed out|ETIMEDOUT|ECONNABORTED/i.test(safeErrorText)) throw new Error('Make reporting webhook timed out.');
  throw new Error('Make reporting webhook network request failed.');
}
const statusCode = Number(result?.statusCode);
if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) {
  if (Number.isInteger(statusCode)) throw new Error(`Make reporting webhook returned HTTP ${statusCode}.`);
  throw new Error('Make reporting webhook returned no verifiable HTTP status.');
}
return [{ json: { report_key: report.report_key, business_date: report.business_date, make_webhook_accepted: true, make_http_status: statusCode, accepted_at: new Date().toISOString() } }];
